 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(length, separators):
        out, start = [], 0
        for p in separators + [length]:
            if start < p:
                out.append((start, p))
            start = p + 1
        return out

    rows, cols = spans(h, sep_rows), spans(w, sep_cols)
    separators = {grid[r][0] for r in sep_rows} | {grid[0][c] for c in sep_cols}
    counts = {}
    for r in range(h):
        for c in range(w):
            if r not in sep_rows and c not in sep_cols and grid[r][c] not in separators:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    if not counts:
        return [row[:] for row in grid]
    background = max(counts, key=counts.get)

    panels = []
    for ri, (r0, r1) in enumerate(rows):
        for ci, (c0, c1) in enumerate(cols):
            marks = {(r-r0, c-c0): grid[r][c]
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != background and grid[r][c] not in separators}
            panels.append((ri, ci, r0, r1, c0, c1, marks))
    source = max(panels, key=lambda p: len(p[6]))
    _, _, _, _, _, _, motif = source
    ph = source[3] - source[2]
    pw = source[5] - source[4]
    out = [row[:] for row in grid]
    for _, (r0, r1) in enumerate(rows):
        for _, (c0, c1) in enumerate(cols):
            if r1-r0 != ph or c1-c0 != pw:
                continue
            for (dr, dc), value in motif.items():
                out[r0+dr][c0+dc] = value
    return out
